66: static inline void nodemask_zero(nodemask_t *mask)
67: {
68: 	struct bitmask tmp;
69: 
70: 	tmp.maskp = (unsigned long *)mask;
71: 	tmp.size = sizeof(nodemask_t) * 8;
72: 	numa_bitmask_clearall(&tmp);
73: }
