151: static unsigned int
152: _getbit(const struct bitmask *bmp, unsigned int n)
153: {
154: 	if (n < bmp->size)
155: 		return (bmp->maskp[n/bitsperlong] >> (n % bitsperlong)) & 1;
156: 	else
157: 		return 0;
158: }
159: 
160: static void
161: _setbit(struct bitmask *bmp, unsigned int n, unsigned int v)
162: {
163: 	if (n < bmp->size) {
164: 		if (v)
165: 			bmp->maskp[n/bitsperlong] |= 1UL << (n % bitsperlong);
166: 		else
167: 			bmp->maskp[n/bitsperlong] &= ~(1UL << (n % bitsperlong));
168: 	}
169: }
170: 
171: int
172: numa_bitmask_isbitset(const struct bitmask *bmp, unsigned int i)
173: {
174: 	return _getbit(bmp, i);
175: }
176: 
177: struct bitmask *
178: numa_bitmask_setall(struct bitmask *bmp)
179: {
180: 	unsigned int i;
181: 	for (i = 0; i < bmp->size; i++)
182: 		_setbit(bmp, i, 1);
183: 	return bmp;
184: }
185: 
186: struct bitmask *
187: numa_bitmask_clearall(struct bitmask *bmp)
188: {
189: 	unsigned int i;
190: 	for (i = 0; i < bmp->size; i++)
191: 		_setbit(bmp, i, 0);
192: 	return bmp;
193: }
194: 
195: struct bitmask *
196: numa_bitmask_setbit(struct bitmask *bmp, unsigned int i)
197: {
198: 	_setbit(bmp, i, 1);
199: 	return bmp;
200: }
201: 
202: struct bitmask *
203: numa_bitmask_clearbit(struct bitmask *bmp, unsigned int i)
204: {
205: 	_setbit(bmp, i, 0);
206: 	return bmp;
207: }
208: 
209: unsigned int
210: numa_bitmask_nbytes(struct bitmask *bmp)
211: {
212: 	return longsperbits(bmp->size) * sizeof(unsigned long);
213: }
214: 
215: /* where n is the number of bits in the map */
216: /* This function should not exit on failure, but right now we cannot really
217:    recover from this. */
218: struct bitmask *
219: numa_bitmask_alloc(unsigned int n)
220: {
221: 	struct bitmask *bmp;
222: 
223: 	if (n < 1) {
224: 		errno = EINVAL;
225: 		numa_error("request to allocate mask for invalid number");
226: 		return NULL;
227: 	}
228: 	bmp = malloc(sizeof(*bmp));
229: 	if (bmp == 0)
230: 		goto oom;
231: 	bmp->size = n;
232: 	bmp->maskp = calloc(longsperbits(n), sizeof(unsigned long));
233: 	if (bmp->maskp == 0) {
234: 		free(bmp);
235: 		goto oom;
236: 	}
237: 	return bmp;
238: 
239: oom:
240: 	numa_error("Out of memory allocating bitmask");
241: 	exit(1);
242: }
243: 
244: void
245: numa_bitmask_free(struct bitmask *bmp)
246: {
247: 	if (bmp == 0)
248: 		return;
249: 	free(bmp->maskp);
250: 	bmp->maskp = (unsigned long *)0xdeadcdef;  /* double free tripwire */
251: 	free(bmp);
252: 	return;
253: }
254: 
255: /* True if two bitmasks are equal */
256: int
257: numa_bitmask_equal(const struct bitmask *bmp1, const struct bitmask *bmp2)
258: {
259: 	unsigned int i;
260: 	for (i = 0; i < bmp1->size || i < bmp2->size; i++)
261: 		if (_getbit(bmp1, i) != _getbit(bmp2, i))
262: 			return 0;
263: 	return 1;
264: }
265: 
266: /* Hamming Weight: number of set bits */
267: unsigned int numa_bitmask_weight(const struct bitmask *bmp)
268: {
269: 	unsigned int i;
270: 	unsigned int w = 0;
271: 	for (i = 0; i < bmp->size; i++)
272: 		if (_getbit(bmp, i))
273: 			w++;
274: 	return w;
275: }
