356: /*
357:  * Find nodes (numa_nodes_ptr), nodes with memory (numa_memnode_ptr)
358:  * and the highest numbered existing node (maxconfigurednode).
359:  */
360: static void
361: set_configured_nodes(void)
362: {
363: 	DIR *d;
364: 	struct dirent *de;
365: 
366: 	numa_memnode_ptr = numa_allocate_nodemask();
367: 	numa_nodes_ptr = numa_allocate_nodemask();
368: 	if (!numa_memnode_ptr || !numa_nodes_ptr)
369: 		return;
370: 
371: 	d = opendir("/sys/devices/system/node");
372: 	if (!d) {
373: 		maxconfigurednode = 0;
374: 	} else {
375: 		while ((de = readdir(d)) != NULL) {
376: 			int nd;
377: 			if (strncmp(de->d_name, "node", 4))
378: 				continue;
379: 			nd = strtoul(de->d_name+4, NULL, 0);
380: 			numa_bitmask_setbit(numa_nodes_ptr, nd);
381: 			numa_bitmask_setbit(numa_memnode_ptr, nd);
382: 			if (maxconfigurednode < nd)
383: 				maxconfigurednode = nd;
384: 		}
385: 		closedir(d);
386: 	}
387: }
