389: static inline int is_digit(char s)
390: {
391: 	return (s >= '0' && s <= '9')
392: 		|| (s >= 'a' && s <= 'f')
393: 		|| (s >= 'A' && s <= 'F');
394: }
395: 
396: /* Is string 'pre' a prefix of string 's'? */
397: static int strprefix(const char *s, const char *pre)
398: {
399: 	return strncmp(s, pre, strlen(pre)) == 0;
400: }
401: 
402: static const char *mask_size_file = "/proc/self/status";
403: static const char *nodemask_prefix = "Mems_allowed:\t";
404: /*
405:  * (do this the way Paul Jackson's libcpuset does it)
406:  * The nodemask values in /proc/self/status are in an
407:  * ascii format that uses 9 characters for each 32 bits of mask.
408:  * (this could also be used to find the cpumask size)
409:  */
410: static void
411: set_nodemask_size(void)
412: {
413: 	FILE *fp;
414: 	char *buf = NULL;
415: 	char *tmp_buf = NULL;
416: 	int digit_len = 0;
417: 	size_t bufsize = 0;
418: 
419: 	if ((fp = fopen(mask_size_file, "r")) == NULL)
420: 		goto done;
421: 
422: 	while (getline(&buf, &bufsize, fp) > 0) {
423: 		if (strprefix(buf, nodemask_prefix)) {
424: 			tmp_buf = buf;
425: 			tmp_buf += strlen(nodemask_prefix);
426: 			while (*tmp_buf != '\n' && *tmp_buf != '\0') {
427: 				if (is_digit(*tmp_buf))
428: 					digit_len++;
429: 				tmp_buf++;
430: 			}
431: 			nodemask_sz = digit_len * 4;
432: 		}
433: 	}
434: 	free(buf);
435: 	fclose(fp);
436: done:
437: 	if (nodemask_sz == 0) {/* fall back on error */
438: 		int pol;
439: 		unsigned long *mask = NULL, *origmask;
440: 		nodemask_sz = 16;
441: 		do {
442: 			nodemask_sz <<= 1;
443: 			origmask = mask;
444: 			mask = realloc(mask, nodemask_sz / 8 + sizeof(unsigned long));
445: 			if (!mask) {
446: 				free(origmask);
447: 				return;
448: 			}
449: 		} while (get_mempolicy(&pol, mask, nodemask_sz, 0, 0) < 0 && errno == EINVAL &&
450: 				nodemask_sz < 4096*8);
451: 		free(mask);
452: 	}
453: }
454: 
455: /*
456:  * Read a mask consisting of a sequence of hexadecimal longs separated by
457:  * commas. Order them correctly and return the number of bits set.
458:  */
459: static int
460: read_mask(char *s, struct bitmask *bmp)
461: {
462: 	char *end = s;
463: 	int tmplen = (bmp->size + bitsperint - 1) / bitsperint;
464: 	unsigned int tmp[tmplen];
465: 	unsigned int *start = tmp;
466: 	unsigned int i, n = 0, m = 0;
467: 
468: 	if (!s)
469: 		return 0;	/* shouldn't happen */
470: 
471: 	i = strtoul(s, &end, 16);
472: 
473: 	/* Skip leading zeros */
474: 	while (!i && *end++ == ',') {
475: 		i = strtoul(end, &end, 16);
476: 	}
477: 
478: 	if (!i)
479: 		/* End of string. No mask */
480: 		return -1;
481: 
482: 	start[n++] = i;
483: 	/* Read sequence of ints */
484: 	while (*end++ == ',') {
485: 		i = strtoul(end, &end, 16);
486: 		start[n++] = i;
487: 
488: 		/* buffer overflow */
489: 		if (n > tmplen)
490: 			return -1;
491: 	}
492: 
493: 	/*
494: 	 * Invert sequence of ints if necessary since the first int
495: 	 * is the highest and we put it first because we read it first.
496: 	 */
497: 	while (n) {
498: 		int w;
499: 		unsigned long x = 0;
500: 		/* read into long values in an endian-safe way */
501: 		for (w = 0; n && w < bitsperlong; w += bitsperint)
502: 			x |= ((unsigned long)start[n-- - 1] << w);
503: 
504: 		bmp->maskp[m++] = x;
505: 	}
506: 	/*
507: 	 * Return the number of bits set
508: 	 */
509: 	return numa_bitmask_weight(bmp);
510: }
