591: /*
592:  * Find the highest cpu number possible (in other words the size
593:  * of a kernel cpumask_t (in bits) - 1)
594:  */
595: static void
596: set_numa_max_cpu(void)
597: {
598: 	int len = 4096;
599: 	int n;
600: 	int olde = errno;
601: 	struct bitmask *buffer;
602: 
603: 	do {
604: 		buffer = numa_bitmask_alloc(len);
605: 		if (!buffer)
606: 			return;
607: 		n = numa_sched_getaffinity_v2_int(0, buffer);
608: 		/* on success, returns size of kernel cpumask_t, in bytes */
609: 		if (n < 0) {
610: 			if (errno == EINVAL) {
611: 				if (len >= 1024*1024)
612: 					break;
613: 				len *= 2;
614: 				numa_bitmask_free(buffer);
615: 				continue;
616: 			} else {
617: 				numa_warn(W_numcpus, "Unable to determine max cpu"
618: 					  " (sched_getaffinity: %s); guessing...",
619: 					  strerror(errno));
620: 				n = sizeof(cpu_set_t);
621: 				break;
622: 			}
623: 		}
624: 	} while (n < 0);
625: 	numa_bitmask_free(buffer);
626: 	errno = olde;
627: 	cpumask_sz = n*8;
628: }
