828: /* (cache the result?) */
829: long long numa_node_size64(int node, long long *freep)
830: {
831: 	size_t len = 0;
832: 	char *line = NULL;
833: 	long long size = -1;
834: 	FILE *f;
835: 	char fn[64];
836: 	int ok = 0;
837: 	int required = freep ? 2 : 1;
838: 
839: 	if (freep)
840: 		*freep = 0;
841: 	sprintf(fn,"/sys/devices/system/node/node%d/meminfo", node);
842: 	f = fopen(fn, "r");
843: 	if (!f)
844: 		return -1;
845: 	while (getdelim(&line, &len, '\n', f) > 0) {
846: 		char *end;
847: 		char *s = strcasestr(line, "kB");
848: 		if (!s)
849: 			continue;
850: 		--s;
851: 		while (s > line && isspace(*s))
852: 			--s;
853: 		while (s > line && isdigit(*s))
854: 			--s;
855: 		if (strstr(line, "MemTotal")) {
856: 			size = strtoull(s,&end,0) << 10;
857: 			if (end == s)
858: 				size = -1;
859: 			else
860: 				ok++;
861: 		}
862: 		if (freep && strstr(line, "MemFree")) {
863: 			*freep = strtoull(s,&end,0) << 10;
864: 			if (end == s)
865: 				*freep = -1;
866: 			else
867: 				ok++;
868: 		}
869: 	}
870: 	fclose(f);
871: 	free(line);
872: 	if (ok != required)
873: 		numa_warn(W_badmeminfo, "Cannot parse sysfs meminfo (%d)", ok);
874: 	return size;
875: }
