1346: numa_parse_bitmap_v1(char *line, unsigned long *mask, int ncpus)
1347: {
1348: 	int i;
1349: 	char *p = strchr(line, '\n');
1350: 	if (!p)
1351: 		return -1;
1352: 
1353: 	for (i = 0; p > line;i++) {
1354: 		char *oldp, *endp;
1355: 		oldp = p;
1356: 		if (*p == ',')
1357: 			--p;
1358: 		while (p > line && *p != ',')
1359: 			--p;
1360: 		/* Eat two 32bit fields at a time to get longs */
1361: 		if (p > line && sizeof(unsigned long) == 8) {
1362: 			oldp--;
1363: 			memmove(p, p+1, oldp-p+1);
1364: 			while (p > line && *p != ',')
1365: 				--p;
1366: 		}
1367: 		if (*p == ',')
1368: 			p++;
1369: 		if (i >= CPU_LONGS(ncpus))
1370: 			return -1;
1371: 		mask[i] = strtoul(p, &endp, 16);
1372: 		if (endp != oldp)
1373: 			return -1;
1374: 		p--;
1375: 	}
1376: 	return 0;
1377: }
